// V148 soldier models and animations.
// Geometry and animation clips come from models-v148/soldiers-v148-{high,low}.bin, generated by
// tools/soldiers_v148 from the same source as the GLB files in models-v148/glb/.
// The rig keeps the fields the rest of the game already uses (body, head, arms, legs, horseLegs)
// so nothing outside the soldier visuals has to change.
import * as T from './vendor/three.module.js';

const MAGIC = 0x3156534B;
let quality = 'medium';
try { quality = localStorage.getItem('kingdoms-quality') || (innerWidth > 760 ? 'high' : 'medium'); } catch {}
// 'high' quality (desktop default) gets the detailed pack; 'medium' (phone default) and 'low' get the light one.
const LOD = quality === 'high' ? 'high' : 'low';
let PACK = null, BLOB = null;
try {
  const res = await fetch(new URL('./models-v148/soldiers-v148-' + LOD + '.bin?v=148a', import.meta.url));
  if (!res.ok) throw Error('HTTP ' + res.status);
  const buf = await res.arrayBuffer(), view = new DataView(buf);
  if (view.getUint32(0, true) !== MAGIC) throw Error('bad soldier pack');
  const len = view.getUint32(4, true);
  PACK = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, 8, len)));
  BLOB = buf.slice(8 + len);
} catch (error) {
  // Older soldier visuals remain available if the pack cannot be loaded (tests in Node, offline copies).
  if (typeof window !== 'undefined') console.warn('V148 soldier models unavailable, using previous visuals:', error?.message || error);
}
export const V148_LOD = LOD;
export const V148_KINDS = Object.freeze(Object.keys(PACK?.kinds || {}));
export const hasV148Soldier = kind => !!PACK?.kinds?.[kind];

const Q = 1 / 8000;
const cloth = new T.MeshStandardMaterial({ vertexColors: true, roughness: .86, metalness: 0 });
const metal = new T.MeshStandardMaterial({ vertexColors: true, roughness: .46, metalness: .38 });
cloth.name = 'v148-cloth'; metal.name = 'v148-metal';
const geometries = new Map();
const tmpColor = new T.Color();
const UPPER = new Set(['chest', 'head', 'upperArm_L', 'upperArm_R', 'forearm_L', 'forearm_R', 'hand_L', 'hand_R']);

function teamColor(token, color) {
  const c = new T.Color(color);
  if (token === 'TEAM_D') c.lerp(new T.Color('#1d1a17'), .42);
  if (token === 'TEAM_L') c.lerp(new T.Color('#ffffff'), .3);
  return c;
}
function wanted(tags, grade, variant, variants) {
  if (!tags) return true;
  const t = tags.split(',');
  for (const tag of t) {
    if (/^v\d+$/.test(tag) && variants > 1 && tag !== 'v' + variant) return false;
  }
  if (grade === 'elite') { if (t.includes('helm_std') || t.includes('mobilized')) return false; }
  else if (grade === 'mobilized') { if (t.includes('armor') || t.includes('elite')) return false; }
  else if (t.includes('elite') || t.includes('mobilized')) return false;
  return true;
}
function variantCount(def) {
  let n = 1;
  for (const c of def.chunks) for (const tag of (c[2] ? c[2].split(',') : [])) { const m = /^v(\d+)$/.exec(tag); if (m) n = Math.max(n, +m[1] + 1); }
  return n;
}
// One BufferGeometry per (bone, toggle group, material); team colours are baked in, which keeps
// every geometry shareable by all soldiers of the same kind, colour, grade and head variant.
function geometryFor(kind, bone, group, mat, color, grade, variant) {
  const def = PACK.kinds[kind];
  def.variants ??= variantCount(def);
  const list = def.chunks.filter(c => c[0] === bone && c[1] === group && c[3] === mat && wanted(c[2], grade, variant, def.variants));
  if (!list.length) return null;
  const team = list.some(c => c[4].startsWith('TEAM'));
  const variantKey = list.some(c => /(^|,)v\d+/.test(c[2])) ? variant : 0;
  const key = [kind, bone, group, mat, team ? color : '', grade, variantKey].join('|');
  if (geometries.has(key)) return geometries.get(key);
  let vCount = 0, iCount = 0;
  for (const c of list) { vCount += c[7]; iCount += c[9]; }
  const pos = new Float32Array(vCount * 3), nrm = new Float32Array(vCount * 3), col = new Float32Array(vCount * 3);
  const idx = new (vCount > 65535 ? Uint32Array : Uint16Array)(iCount);
  let vo = 0, io = 0;
  for (const c of list) {
    const [, , , , hex, po, no, n, ioff, ic] = c;
    const p = new Int16Array(BLOB, po, n * 3), q = new Int8Array(BLOB, no, n * 3), ind = new Uint16Array(BLOB, ioff, ic);
    const rgb = hex.startsWith('TEAM') ? teamColor(hex, color) : tmpColor.set(hex);
    for (let i = 0; i < n * 3; i++) { pos[vo * 3 + i] = p[i] * Q; nrm[vo * 3 + i] = q[i] / 127; }
    for (let i = 0; i < n; i++) { col[(vo + i) * 3] = rgb.r; col[(vo + i) * 3 + 1] = rgb.g; col[(vo + i) * 3 + 2] = rgb.b; }
    for (let i = 0; i < ic; i++) idx[io + i] = ind[i] + vo;
    vo += n; io += ic;
  }
  const g = new T.BufferGeometry();
  g.setAttribute('position', new T.BufferAttribute(pos, 3));
  g.setAttribute('normal', new T.BufferAttribute(nrm, 3, false));
  g.setAttribute('color', new T.BufferAttribute(col, 3));
  g.setIndex(new T.BufferAttribute(idx, 1));
  g.computeBoundingSphere();
  g.userData.shared = true; g.userData.v148 = key;
  geometries.set(key, g);
  return g;
}

const LEGACY_KIND = {
  spearman: 'spearman', bronze_spearman: 'spearman', militia: 'spearman', scout: 'spearman', javelinman: 'spearman', pikeman: 'halberdier',
  axeman: 'axeman', bronze_axeman: 'axeman', infantry: 'infantry', man_at_arms: 'man_at_arms', halberdier: 'halberdier',
  archer: 'archer', bronze_archer: 'archer', iron_archer: 'archer', crossbowman: 'crossbowman', slinger: 'slinger',
  arquebusier: 'musketeer', musketeer: 'musketeer', rifleman: 'rifleman', line_infantry: 'rifleman', modern_infantry: 'rifleman', rocket_team: 'rifleman',
  cavalry: 'cavalry', bronze_cavalry: 'cavalry', knight: 'knight', heavy_cavalry: 'heavy_cavalry', cuirassier: 'cavalry', dragoon: 'cavalry'
};

export function createV148Soldier(parent, x, z, color, kind, grade = 'standard') {
  const def = PACK.kinds[kind];
  def.variants ??= variantCount(def);
  const variant = Math.abs(Math.round(x * 7.31 + z * 3.17)) % def.variants;
  const root = new T.Group(), bones = {};
  root.name = 'v148:' + kind;
  for (const [name, parentName, offset] of def.bones) {
    const g = new T.Group();
    g.name = name;
    g.position.set(offset[0], offset[1], offset[2]);
    const r = def.rest[name];
    if (r) g.rotation.set(r[0], r[1], r[2]);
    (parentName ? bones[parentName] : root).add(g);
    bones[name] = g;
    g.userData.restPosition = g.position.clone();
  }
  const groups = new Map();
  for (const c of def.chunks) groups.set(c[0] + '\u0000' + c[1] + '\u0000' + c[3], [c[0], c[1], c[3]]);
  const toggles = {};
  for (const [bone, group, mat] of groups.values()) {
    const geo = geometryFor(kind, bone, group, mat, color, grade, variant);
    if (!geo) continue;
    const mesh = new T.Mesh(geo, mat === 'metal' ? metal : cloth);
    mesh.castShadow = true; mesh.receiveShadow = true;
    if (group) { const holder = new T.Group(); holder.name = group; holder.add(mesh); bones[bone].add(holder); (toggles[group] ??= []).push(holder); }
    else bones[bone].add(mesh);
  }
  const rig = {
    v148: true, def, kind: LEGACY_KIND[kind] || kind, unitKind: kind, bones, toggles,
    body: bones.body, head: bones.head, arms: [bones.upperArm_L, bones.upperArm_R], legs: [bones.thigh_L, bones.thigh_R],
    horseLegs: ['FL', 'FR', 'HL', 'HR'].map(k => bones['horseLeg_' + k]).filter(Boolean),
    riding: !!def.riding, dismountable: kind === 'dragoon', rangedChariot: false, phase: x * 2 + z, archetype: 'v148', variant
  };
  root.userData = { unitKind: kind, grade, factionColor: color, v148: true, rig };
  root.position.set(x, 0, z);
  parent.add(root);
  return root;
}

function sample(clip, t, out) {
  const f = clip.f, n = f.length;
  if (n === 1) return copyFrame(f[0], f[0], 0, out);
  let u = t / clip.d;
  if (clip.loop) { u = ((u % 1) + 1) % 1; const p = u * n, i = Math.floor(p) % n; return copyFrame(f[i], f[(i + 1) % n], p - Math.floor(p), out); }
  u = Math.min(1, Math.max(0, u)); const p = u * (n - 1), i = Math.min(n - 2, Math.floor(p));
  return copyFrame(f[i], f[i + 1], p - i, out);
}
function copyFrame(a, b, k, out) {
  out.r ??= {}; out.t ??= {};
  for (const bone in a.r) { const x = a.r[bone], y = b.r[bone] || x; const o = out.r[bone] ??= [0, 0, 0]; o[0] = x[0] + (y[0] - x[0]) * k; o[1] = x[1] + (y[1] - x[1]) * k; o[2] = x[2] + (y[2] - x[2]) * k; }
  for (const bone in out.t) if (!a.t[bone]) out.t[bone].fill(0);
  for (const bone in a.t) { const x = a.t[bone], y = b.t[bone] || x; const o = out.t[bone] ??= [0, 0, 0]; o[0] = x[0] + (y[0] - x[0]) * k; o[1] = x[1] + (y[1] - x[1]) * k; o[2] = x[2] + (y[2] - x[2]) * k; }
  return out;
}
const baseFrame = {}, layerFrame = {};
function apply(r, frame, filter = null, weight = 1) {
  for (const bone in frame.r) {
    if (filter && !filter.has(bone)) continue;
    const g = r.bones[bone]; if (!g) continue; const v = frame.r[bone];
    if (weight >= 1) g.rotation.set(v[0], v[1], v[2]);
    else g.rotation.set(g.rotation.x + (v[0] - g.rotation.x) * weight, g.rotation.y + (v[1] - g.rotation.y) * weight, g.rotation.z + (v[2] - g.rotation.z) * weight);
  }
  if (filter) return;
  for (const bone in frame.t) { const g = r.bones[bone]; if (!g) continue; const v = frame.t[bone], p = g.userData.restPosition; g.position.set(p.x + v[0], p.y + v[1], p.z + v[2]); }
}

export function animateV148Soldier(root, time, moving = false, attack = false) {
  const r = root.userData.rig, clips = r.def.clips;
  const weapon = typeof attack === 'object' ? attack?.weapon : null, swordDrawn = weapon === 'sword';
  const dismounted = r.dismountable && !!attack?.dismounted;
  const t = r.toggles;
  if (t.bowWeapon) for (const g of t.bowWeapon) g.visible = !swordDrawn;
  if (t.swordWeapon) for (const g of t.swordWeapon) g.visible = swordDrawn;
  if (t.swordSheath) for (const g of t.swordSheath) g.visible = !swordDrawn;
  if (t.mountedGun) for (const g of t.mountedGun) g.visible = weapon === 'gun' || dismounted;
  if (t.sideWeapon) for (const g of t.sideWeapon) g.visible = weapon !== 'gun' && !dismounted;
  const phase = typeof attack === 'object' && attack ? attack.phase ?? -1 : (attack ? .4 : -1), active = phase >= 0 && phase <= 1;
  const local = time + r.phase * .37;
  const base = dismounted ? clips.dismounted : (moving ? (r.riding ? clips.run : clips.walk) : clips.idle);
  apply(r, sample(base, moving ? time * (r.riding ? 1 : 1) + r.phase * .05 : local, baseFrame));
  if (active) {
    const name = dismounted ? 'dismounted_attack' : (swordDrawn && clips.attack_sword ? 'attack_sword' : weapon === 'gun' && clips.attack_gun ? 'attack_gun' : 'attack');
    const clip = clips[name] || clips.attack;
    sample(clip, phase * clip.d, layerFrame);
    apply(r, layerFrame, moving || r.riding ? UPPER : null);
  } else if (attack && typeof attack === 'object' && attack.formed > .4 && !moving) {
    const pose = attack.formation === 'spear_wall' ? clips.brace : attack.formation === 'shield_wall' ? clips.shield_wall : null;
    if (pose) { sample(pose, 0, layerFrame); apply(r, layerFrame, UPPER, Math.min(1, (attack.formed - .4) / .4)); }
  }
  if (attack && typeof attack === 'object' && attack.hit && clips.hit) { sample(clips.hit, .08, layerFrame); apply(r, layerFrame, UPPER, .8); }
}
